'use strict';
const films=[
 {file:'tsho-rolpa',name:'Tsho Rolpa',place:'TSHO ROLPA · NEPAL',title:'Where the earth meets the sky.',caption:'A real aerial journey over Tsho Rolpa’s glacial water and surrounding Himalayan landscape.',author:'Raju Shrestha',source:'https://www.pexels.com/video/aerial-view-of-tsho-rolpa-lake-in-nepal-29747126/',start:14},
 {file:'nepal-hills',name:'Nepal’s hill country',place:'THE MIDDLE HILLS · NEPAL',title:'Above the everyday.',caption:'A quiet flight through Nepal’s mist-covered hills, filmed from above.',author:'Prabesh Rai',source:'https://www.pexels.com/video/nepali-village-drone-view-27817134/',start:0},
 {file:'phewa-lake',name:'Phewa Lake',place:'PHEWA LAKE · POKHARA',title:'Take a slower breath.',caption:'The lakeside world of Pokhara, seen from the air above Phewa Lake.',author:'Pritam Chhetri',source:'https://www.pexels.com/video/aerial-view-of-phewa-lake-in-pokhara-nepal-38680457/',start:0}
];
let cinemaQuality=navigator.connection?.saveData?'light':'detail',cinemaFilmIndex=0,qualityRequest=0;
try{const q=localStorage.getItem('nepal-film-quality');if(['light','detail'].includes(q))cinemaQuality=q;}catch{}
const cinemaAsset=(film,quality=cinemaQuality)=>`assets/${quality==='detail'?'journal':'immersive'}/${film.file}.mp4`;
const reducedMotion=matchMedia('(prefers-reduced-motion: reduce)');let motionEnabled=!reducedMotion.matches&&!navigator.connection?.saveData;let heroInView=true;let heroFilm=0;
const backgroundVideo=$('#hero-video');backgroundVideo.muted=true;
function updateMotionUI(){const paused=!motionEnabled;$('#motion-toggle').innerHTML=(paused?'▶':'Ⅱ')+` <span>${paused?'PLAY MOTION':'PAUSE MOTION'}</span>`;$('#motion-toggle').setAttribute('aria-pressed',motionEnabled);$('#motion-toggle').setAttribute('aria-label',paused?'Play background motion':'Pause background motion');}
function syncBackground(){if(motionEnabled&&heroInView&&!document.hidden&&!document.querySelector('dialog[open]')){if(!backgroundVideo.getAttribute('src'))loadHeroFilm(heroFilm);else backgroundVideo.play().catch(()=>{backgroundVideo.classList.remove('is-playing');motionEnabled=false;updateMotionUI();});}else backgroundVideo.pause();}
function loadHeroFilm(index){heroFilm=index;const film=films[index];backgroundVideo.pause();backgroundVideo.classList.remove('is-playing');$('#hero-image').src=`assets/journal/${film.file}-poster.jpg`;$('#hero-image').alt=film.caption;$('#hero-location').textContent=film.place;$$('[data-film-scene]').forEach(b=>{const active=+b.dataset.filmScene===index;b.classList.toggle('active',active);b.setAttribute('aria-pressed',active);});backgroundVideo.onloadedmetadata=()=>{if(film.start&&backgroundVideo.duration>film.start)backgroundVideo.currentTime=film.start;syncBackground();};backgroundVideo.onplaying=()=>backgroundVideo.classList.add('is-playing');backgroundVideo.onerror=()=>{if(backgroundVideo.getAttribute('src')?.includes('assets/journal/')){backgroundVideo.src=cinemaAsset(film,'light');backgroundVideo.load();return;}backgroundVideo.classList.remove('is-playing');motionEnabled=false;updateMotionUI();};if(motionEnabled){backgroundVideo.src=cinemaAsset(film,innerWidth>=800&&!navigator.connection?.saveData?'detail':'light');backgroundVideo.load();}else{backgroundVideo.removeAttribute('src');backgroundVideo.load();}}
$$('[data-film-scene]').forEach(b=>b.addEventListener('click',()=>loadHeroFilm(+b.dataset.filmScene)));
$('#motion-toggle').addEventListener('click',()=>{motionEnabled=!motionEnabled;updateMotionUI();syncBackground();});
new IntersectionObserver(entries=>{heroInView=entries[0].isIntersecting;syncBackground();},{threshold:.05}).observe($('#home'));
new MutationObserver(syncBackground).observe(document.body,{subtree:true,attributes:true,attributeFilter:['open']});
document.addEventListener('visibilitychange',syncBackground);reducedMotion.addEventListener('change',()=>{motionEnabled=!reducedMotion.matches;updateMotionUI();syncBackground();});updateMotionUI();

function renderFilmQuality(){const f=films[cinemaFilmIndex];$('#film-quality').value=cinemaQuality;$('#film-quality-note').textContent=cinemaQuality==='detail'?'1920 × 1080 · source detail':'Smaller file · quicker loading';$('#video-credit').innerHTML=`Film: <a href="${f.source}" target="_blank" rel="noopener">${f.author} / Pexels ↗</a> · Silent aerial footage · ${cinemaQuality==='detail'?'Full HD source edition':'Lightweight web edition'}`;}
function openFilm(index){qualityRequest++;cinemaFilmIndex=index;const film=films[index],video=$('#cinema-video');video.pause();$('#film-modal-title').textContent=film.name;$('#film-caption').textContent=film.caption;renderFilmQuality();$$('.film-switcher button').forEach(b=>b.classList.toggle('active',+b.dataset.film===index));video.poster=`assets/journal/${film.file}-poster.jpg`;video.src=cinemaAsset(film);video.setAttribute('aria-label',film.name+' travel film');if(!$('#film-dialog').open)openDialog($('#film-dialog'));video.load();video.play().catch(()=>{});}
$('#film-quality').addEventListener('change',e=>{const video=$('#cinema-video'),time=video.currentTime,playing=!video.paused;cinemaQuality=e.target.value;try{localStorage.setItem('nepal-film-quality',cinemaQuality);}catch{}const request=++qualityRequest;renderFilmQuality();video.addEventListener('loadedmetadata',()=>{if(request!==qualityRequest)return;video.currentTime=Math.min(time,Math.max(0,video.duration-.1));if(playing)video.play().catch(()=>{});},{once:true});video.src=cinemaAsset(films[cinemaFilmIndex]);video.load();});
document.addEventListener('click',e=>{const b=e.target.closest('[data-film]');if(b)openFilm(+b.dataset.film);});
$('#film-dialog').addEventListener('close',()=>{qualityRequest++;$('#cinema-video').pause();$('#cinema-video').removeAttribute('src');$('#cinema-video').load();});

const panoScenes={
 gosaikunda:{name:'A lake. A thousand perspectives.',location:'GOSAIKUNDA / RASUWA',kind:'REAL 360° PHOTOGRAPHY · 2019',poster:'gosaikunda-360',credit:'Gosaikunda: Acharya Bipin / <a href="https://commons.wikimedia.org/wiki/File:Gosaikunda_360.jpg" target="_blank" rel="noopener">Wikimedia Commons</a> · <a href="https://creativecommons.org/licenses/by-sa/4.0/" target="_blank" rel="noopener">CC BY-SA 4.0</a> · Resized and recompressed.'},
 temple:{name:'Step into a living tradition.',location:'RAM MANDIR / PASHUPATINATH, KATHMANDU',kind:'REAL 360° PHOTOGRAPHY · 2019',poster:'ram-mandir-360',credit:'Ram Mandir: Gaurav Dhwaj Khadka / <a href="https://commons.wikimedia.org/wiki/File:Ram_Mandir_360_View_Nepal.jpg" target="_blank" rel="noopener">Wikimedia Commons</a> · <a href="https://creativecommons.org/licenses/by-sa/4.0/" target="_blank" rel="noopener">CC BY-SA 4.0</a> · Resized and recompressed.'},
 flight:{name:'Take the scenic flight.',location:'HIMALAYAN DREAM / AN ARTISTIC INTERPRETATION',kind:'INTERACTIVE 3D · IMAGINED LANDSCAPE',poster:'himalayan-dreamscape',credit:'A procedural 3D landscape inspired by the Himalayas, with a moving camera and interactive controls. An artistic interpretation, not a geographic reconstruction or real drone footage.'}
};
let viewer=null;let selectedPano='gosaikunda';let entering=false;let sceneRequest=0;
function setRotationUI(){const active=!!viewer?.auto;$('#rotate-view').textContent=active?'Ⅱ':'▶';$('#rotate-view').setAttribute('aria-pressed',active);$('#rotate-view').setAttribute('aria-label',active?'Pause automatic rotation':'Start automatic rotation');}
async function selectPanorama(name,activate=false){selectedPano=name;const s=panoScenes[name];$('#scene-kind').textContent=s.kind;$('#scene-location').textContent=s.location;$('#scene-name').textContent=s.name;$('#immersive-attribution').innerHTML=s.credit;$('#immersion-poster').src=`assets/immersive/${s.poster}.jpg`;$('#immersion-poster').alt=s.name;$$('[data-panorama]').forEach(b=>{b.classList.toggle('active',b.dataset.panorama===name);b.setAttribute('aria-pressed',b.dataset.panorama===name)});if(!viewer&&!activate)return;const req=++sceneRequest;$('#viewer-loading').hidden=false;$('#immersion-intro').hidden=true;$('#immersion-stage').classList.add('is-active');try{if(!viewer){const callback=yaw=>{$('#compass-needle').style.transform=`rotate(${-yaw}deg)`;};let Renderer;try{const probe=document.createElement('canvas');if(!probe.getContext('webgl2'))throw new Error('WebGL unavailable');Renderer=(await import('./immersive-viewer.js')).NepalViewer;viewer=new Renderer($('#immersive-canvas'),callback);}catch{Renderer=(await import('./software-viewer.js')).NepalViewer;viewer=new Renderer($('#immersive-canvas'),callback);}}if(req!==sceneRequest)return;await viewer.load(name);if(req!==sceneRequest)return;$('#viewer-controls').hidden=false;$('#viewer-hint').hidden=false;$('#viewer-hint').textContent=name==='flight'?'↔ DRAG TO ORBIT · + / − TO MOVE CLOSER':'↔ DRAG TO LOOK AROUND · + / − TO ZOOM';setRotationUI();$('#immersive-canvas').focus({preventScroll:true});}catch(error){$('#immersion-stage').classList.remove('is-active');$('#immersion-intro').hidden=false;$('#immersion-intro').querySelector('h3').textContent='Explore the wide view.';$('#immersion-intro').querySelector('p').textContent='This browser could not open the 3D view. Try reloading or another browser.';$('#enter-360').textContent='Try again ↗';viewer?.destroy();viewer=null;console.warn('Immersive view unavailable:',error.message);}finally{if(req===sceneRequest)$('#viewer-loading').hidden=true;}}
$('#enter-360').addEventListener('click',()=>{if(!entering){entering=true;selectPanorama(selectedPano,true).finally(()=>entering=false);}});$$('[data-panorama]').forEach(b=>b.addEventListener('click',()=>selectPanorama(b.dataset.panorama,true)));
$('#rotate-view').addEventListener('click',()=>{if(viewer){viewer.auto=!viewer.auto;setRotationUI();}});$('#zoom-in').addEventListener('click',()=>viewer?.zoom(-7));$('#zoom-out').addEventListener('click',()=>viewer?.zoom(7));$('#reset-view').addEventListener('click',()=>viewer?.reset());$('#immersive-canvas').addEventListener('viewer-rotation-change',setRotationUI);$('#immersive-canvas').addEventListener('viewer-error',e=>{notify(e.detail);$('#viewer-hint').textContent=e.detail;});
const stage=$('#immersion-stage');let expandedView=false;
function expandFallback(){expandedView=!expandedView;stage.classList.toggle('expanded',expandedView);document.body.classList.toggle('viewer-expanded',expandedView);$('#fullscreen-view').setAttribute('aria-label',expandedView?'Exit expanded view':'Expand immersive view');viewer?.resize();}
$('#fullscreen-view').addEventListener('click',async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else if(stage.requestFullscreen)await stage.requestFullscreen();else expandFallback();}catch{expandFallback();}});
document.addEventListener('fullscreenchange',()=>{$('#fullscreen-view').setAttribute('aria-label',document.fullscreenElement?'Exit fullscreen view':'Expand immersive view');viewer?.resize();});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&expandedView)expandFallback();});

const provinces=[
 {id:'koshi',name:'Koshi',number:'01',title:'Where Nepal meets the sky.',description:'Explore sixteen place guides, all fourteen districts, real Khumbu films and a personal Koshi travel notebook. From Everest to the tea hills and wetlands, follow the first light.',places:['Everest & the Khumbu','Ilam tea country','Koshi Tappu wetlands'],image:'koshi/everest',alt:'Everest seen from Gokyo Ri, Koshi Province',detail:'koshi-guide',source:'https://ntb.gov.np/en/koshi-province',theme:'MOUNTAINS · TEA HILLS · WETLANDS'},
 {id:'madhesh',name:'Madhesh',number:'02',title:'A landscape of living stories.',description:'Explore twelve place guides, all eight districts and real Janakpur films. Discover Mithila culture, sacred ponds, Birgunj and Parsa, with your own routes and travel notebook.',places:['Janakpur & Janaki Mandir','Maithil art traditions','The southern plains'],image:'madhesh/janaki',alt:'Janaki Mandir in Janakpurdham',detail:'madhesh-guide',source:'https://ntb.gov.np/en/janakpur',theme:'MITHILA · ART · PILGRIMAGE'},
 {id:'bagmati',name:'Bagmati',number:'03',title:'Where Nepal comes together.',description:'Explore sixteen destination guides and all thirteen districts, from the Kathmandu Valley to Langtang and Chitwan. Find real films, living heritage and a personal Bagmati travel notebook.',places:['Kathmandu, Patan & Bhaktapur','Langtang & Gosaikunda','Chitwan & the hill districts'],image:'bagmati/patan',alt:'Patan Durbar Square in Lalitpur, Bagmati',detail:'bagmati-guide',source:'https://ntb.gov.np/bagmati-province',theme:'HERITAGE · HIMALAYAS · FOREST'},
 {id:'gandaki',name:'Gandaki',number:'04',title:'Where wonder finds its reflection.',description:'Explore eighteen destination guides and all eleven districts, from Pokhara’s lakes to Annapurna, Mustang and the southern lowlands. Real aerial films, village stories and your own Gandaki travel notebook.',places:['Pokhara, Phewa & Begnas','Annapurna, Manang & Mustang','Hill villages & Nawalpur'],image:'gandaki/pokhara',alt:'Phewa Lake and the hills around Pokhara',detail:'gandaki-guide',source:'https://ntb.gov.np/gandaki-province',theme:'LAKES · HIMALAYAS · VILLAGES'},
 {id:'lumbini',name:'Lumbini',number:'05',title:'A journey toward peace.',description:'Explore eighteen destination guides and all twelve districts, from the Buddha’s birthplace to Bardiya’s forests, Palpa’s old streets and the western hills. Real photography, a Butwal time-lapse, living culture and a personal travel notebook.',places:['Lumbini, Tilaurakot & Ramagrama','Bardiya, Banke & wetlands','Palpa, Rapti Valley & the hills'],image:'lumbini/lumbini',alt:'Maya Devi Temple beyond the Sacred Garden in Lumbini',detail:'lumbini-guide',source:'https://ntb.gov.np/lumbini-province',theme:'SACRED PATHS · WILDLIFE · HILLS'},
 {id:'karnali',name:'Karnali',number:'06',title:'Where wonder runs wild.',description:'Explore eighteen destination guides across all ten districts: blue lakes, ancient valleys, hill towns and the remote Himalayas. Begin in Birendranagar and find a journey that fits your pace.',places:['Rara, Phoksundo & Kupinde','Dolpo, Humla & high valleys','Surkhet, Sinja & Dailekh'],image:'karnali/phoksundo',alt:'Blue water and mountain slopes at Phoksundo Lake in Dolpa',detail:'karnali-guide',source:'https://ntb.gov.np/en/karnali-province',theme:'BLUE LAKES · ANCIENT VALLEYS · HIGH HORIZONS'},
 {id:'sudurpaschim',name:'Sudurpashchim',number:'07',title:'Let the far west surprise you.',description:'Explore eleven detailed place guides, real Khaptad footage, all nine districts and three route ideas. Keep your own budget, packing list and travel notes in one Far West journey.',places:['Khaptad National Park','Shuklaphanta National Park','Api Nampa Conservation Area'],image:'farwest/khaptad-mist',alt:'Mist over Khaptad National Park in Sudurpashchim',detail:'farwest-guide',source:'https://ntb.gov.np/en/sudurpaschim-province',theme:'UPLANDS · GRASSLANDS · QUIETER PATHS'}
];
$('.province-tabs').innerHTML=provinces.map((p,i)=>`<button role="tab" aria-selected="${i===0}" aria-controls="province-panel" id="province-${p.id}" data-province="${p.id}" tabindex="${i===0?0:-1}"><span>${p.number}</span>${p.name}</button>`).join('');
function renderProvince(id){const p=provinces.find(x=>x.id===id);$$('[data-province]').forEach(b=>{const active=b.dataset.province===id;b.classList.toggle('active',active);b.setAttribute('aria-selected',active);b.tabIndex=active?0:-1;});$('#province-panel').setAttribute('aria-labelledby','province-'+id);$('#province-panel').innerHTML=`<div class="province-visual">${p.image?`<img src="assets/${p.image}.jpg" alt="${p.alt}" loading="lazy">`:`<div class="west-art"><svg><use href="#mountain"/></svg><span>Go a little<br><em>farther.</em></span><small>THE FAR WEST / NEPAL</small></div>`}<span class="province-number">${p.number}</span></div><div class="province-copy"><div class="eyebrow">${p.theme}</div><h3>${p.title}</h3><p>${p.description}</p><ul>${p.places.map(x=>`<li>${x}</li>`).join('')}</ul>${p.detail?`<button class="text-link" data-detail="${p.detail}">Start exploring ${icon('arrow')}</button>`:`<a class="text-link" href="${p.source}" target="_blank" rel="noopener">Explore official regional guidance ↗</a>`}</div>`;}
$$('[data-province]').forEach((b,i)=>{b.addEventListener('click',()=>renderProvince(b.dataset.province));b.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const next=e.key==='Home'?0:e.key==='End'?6:(i+(e.key==='ArrowRight'?1:-1)+7)%7;renderProvince(provinces[next].id);$$('[data-province]')[next].focus();});});renderProvince('koshi');

const trailDetails={foothills:{image:'annapurna',title:'Start with the foothills.',text:'Choose a village walk in the Annapurna foothills or near the Kathmandu Valley, based on your walking experience, weather and local advice. A shorter trail can still hold a very big view.',points:['Ask about the actual elevation gain and walking surface.','Choose a local guide and an itinerary with room to rest.','Confirm access, transport and overnight arrangements.'],link:'https://ntb.gov.np/things-to-do/hiking'},annapurna:{image:'sunrise',title:'Into the Annapurna landscape.',text:'The Annapurna region includes routes with very different lengths, elevations and demands. Decide which journey suits you before fixing a schedule, and let acclimatization and local conditions set the pace.',points:['Distinguish foothill walks from high-altitude routes.','Confirm permits, guide requirements and trail conditions.','Keep weather and transport buffer days.'],link:'https://ntb.gov.np/en/annapurna-conservation-area'},everest:{image:'everest',title:'Take your time in the Khumbu.',text:'An Everest-region trek is a high-altitude journey through extraordinary landscapes and Sherpa communities. It deserves a purpose-built schedule, experienced guidance and more time than the walking days alone.',points:['Plan a gradual ascent with acclimatization days.','Arrange appropriate insurance and local support.','Allow buffers around flights and changing weather.'],link:'https://ntb.gov.np/everest'},remote:{image:'rara',title:'The journey is part of the place.',text:'Rara and the remote west ask for more flexibility in transport and accommodation. Work with people who know the current conditions, and choose a route that supports local communities.',points:['Confirm route-specific access and permits.','Plan for limited infrastructure and transport changes.','Allow enough days for both the approach and the return.'],link:'https://ntb.gov.np/en/karnali-province'}};
$$('[data-trail]').forEach(b=>b.addEventListener('click',()=>{const t=trailDetails[b.dataset.trail];$('#detail-content').innerHTML=`<img class="detail-image" src="assets/${t.image}.jpg" alt="Nepal mountain travel inspiration"><div class="detail-copy"><div class="eyebrow">A STARTING POINT FOR YOUR JOURNEY</div><h2>${t.title}</h2><p>${t.text}</p><h3>Before the first step.</h3><ul>${t.points.map(x=>`<li>${x}</li>`).join('')}</ul><a class="text-link" href="${t.link}" target="_blank" rel="noopener">Read official travel guidance ↗</a></div>`;openDialog($('#detail-dialog'));}));
$$('[data-culture]').forEach(b=>b.addEventListener('click',()=>{$('#detail-content').innerHTML=`<img class="detail-image" src="assets/janakpur.jpg" alt="Janaki Mandir in Janakpur"><div class="detail-copy"><div class="eyebrow">MEET NEPAL THROUGH ITS COMMUNITIES</div><h2>Culture is a <em>conversation.</em></h2><p>There is no single story of Nepal. Newar craftsmanship in Kathmandu Valley, Sherpa life in the Khumbu, Maithil art in Janakpur, Tharu traditions in the lowlands and many other communities give each journey its own texture.</p><h3>Make room for connection.</h3><ul><li>Choose community-led walks, workshops and locally run stays.</li><li>Meet artisans through their shops and studios; pay fairly for their work.</li><li>Share food with a local host and ask about the story behind it.</li><li>Ask before photographing people or joining a religious activity.</li><li>For festivals such as Tihar, Indra Jatra or Chhath, check local dates and participate respectfully.</li></ul><a class="text-link" href="https://ntb.gov.np/" target="_blank" rel="noopener">Discover culture with Nepal Tourism Board ↗</a></div>`;openDialog($('#detail-dialog'));}));
$('#credits-button').addEventListener('click',()=>{$('#immersive-credits').innerHTML=`<p class="credit-note">Karnali photography, films and research: <a href="karnali.html#sources">View creators, licenses and sources ↗</a></p><p class="credit-note">Lumbini photography, films and research: <a href="lumbini.html#sources">View creators, licenses and sources ↗</a></p><p class="credit-note">Gandaki photography, films and research: <a href="gandaki.html#sources">View creators, licenses and sources ↗</a></p><p class="credit-note">Bagmati photography, films and research: <a href="bagmati.html#sources">View creators, licenses and sources ↗</a></p><p class="credit-note">Madhesh photography and films: <a href="madhesh.html#sources">View creators, licenses and research ↗</a></p><p class="credit-note">New Koshi photography and films: <a href="koshi.html#sources">View all Koshi creators, licenses and research ↗</a></p>${films.map(f=>`<div class="credit-item"><span>${f.name} · aerial film</span><a href="${f.source}" target="_blank" rel="noopener">${f.author} / Pexels ↗</a></div>`).join('')}<p class="credit-note">Films are silent. Full HD source editions and smaller web editions are available under the <a href="https://www.pexels.com/license/" target="_blank" rel="noopener">Pexels License</a>.</p><p class="credit-note">${panoScenes.gosaikunda.credit}</p><p class="credit-note">${panoScenes.temple.credit}</p><p class="credit-note">The resized panorama files remain licensed under CC BY-SA 4.0. They are photographs captured in 2019, not live views.</p><p class="credit-note">“Himalayan dreamscape” is an AI-created artistic image, not a photograph of an exact place. “Himalayan flight” is an imagined procedural 3D landscape, rendered with a compatible canvas renderer or <a href="https://threejs.org" target="_blank" rel="noopener">Three.js</a> (MIT license).</p>`;});
